contract InvMutTest {
    C c;
    address public bankBefore;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount == 10, "must send exactly ticket amount");
        require(address(this).balance >= amount, "insufficient balance");

        bankBefore = c.bank(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint bankBalBefore = bankBefore.balance;

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = address(c).balance;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint bankBalAfter = bankBefore.balance;

        assert(
            reverted
                ? (potAfter == potBefore && balAfter == balBefore && bankBalAfter == bankBalBefore)
                : (
                    (potAfter == potBefore + amount && balAfter == balBefore + amount)
                    || (potAfter == 0 && balAfter == balBefore)
                )
        );
    }

    receive() external payable {}
}

