    EtherLotto c;
    address public bankBefore;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        amount = 10;
        vm.assume(address(this).balance >= amount);
        try c.bank() returns (address __r) { bankBefore = __r; } catch { return; }
        uint balBefore = address(c).balance;
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        uint bankBalBefore = bankBefore.balance;
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balAfter = address(c).balance;
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        uint bankBalAfter = bankBefore.balance;
        assertTrue(reverted
                ? (potAfter == potBefore && balAfter == balBefore && bankBalAfter == bankBalBefore)
                : (
                    (potAfter == potBefore + amount && balAfter == balBefore + amount)
                    || (potAfter == 0 && balAfter == balBefore)
                ));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
